section.programlisting:

List<GlossaryEntry> glossary = List.of(
    new GlossaryEntry("LIB-1", "Apache OpenNLP"),
    new GlossaryEntry("ALG-42", "maximum entropy model"),
    new GlossaryEntry("ALG-7", "perceptron model"));

DocumentAnalyzer analyzer = DocumentAnalyzer.builder()
    .add(new TokenizerAnnotator(WhitespaceTokenizer.INSTANCE))
    .add(new GlossaryAnnotator(new AhoCorasickGlossaryMatcher(glossary, true)))
    .build();

Document document = analyzer.analyze(
    "Apache OpenNLP ships a Maximum Entropy model and a perceptron model.");

List<Annotation<GlossaryMatch>> hits = document.get(GlossaryAnnotator.GLOSSARY);
// three hits: "Apache OpenNLP", "Maximum Entropy model", "perceptron model"


AhoCorasickGlossaryMatcher matcher = new AhoCorasickGlossaryMatcher(
    List.of(new GlossaryEntry("ST", "strasse")),
    true,
    GermanUmlautCharSequenceNormalizer.getInstance());

List<GlossaryMatch> hits = matcher.match("Die Straße ist frei.");
// one hit whose span covers the original "Straße"


TermAnalyzer terms = TermAnalyzer.builder()
    .caseFold()
    .stem(new SnowballStemmerFactory(SnowballStemmer.ALGORITHM.ENGLISH))
    .build();

TermAnalyzingGlossaryMatcher matcher = new TermAnalyzingGlossaryMatcher(
    List.of(new GlossaryEntry("FOOD", "hot dog")), terms);

List<GlossaryMatch> hits = matcher.match("the hot dogs were cold");
// one hit whose span covers the original "hot dogs"


TermAnalyzer analyzer = TermAnalyzer.builder()
    .caseFold()
    .stem(new SnowballStemmerFactory(SnowballStemmer.ALGORITHM.ENGLISH))
    .build();

List<GlossaryEntry> glossary = List.of(
    new GlossaryEntry("NYC", "New York City"),
    new GlossaryEntry("FOOD", "hot dog"));

GlossaryMatcher exact = new AhoCorasickGlossaryMatcher(glossary, true);
GlossaryMatcher inflected = new TermAnalyzingGlossaryMatcher(glossary, analyzer);
GlossaryMatcher composite = new CompositeGlossaryMatcher(List.of(exact, inflected));

List<GlossaryMatch> matches = composite.match("Hot dogs are sold across New York City.");
// two hits in text order: FOOD covering "Hot dogs" (inflected path),
// NYC covering "New York City" (exact path wins over the inflected duplicate)
